CREATE OR REPLACE FUNCTION public.team_quizzes(_team uuid) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'public' AS $function$
 SELECT coalesce(jsonb_agg(jsonb_build_object('id',z.id,'title_en',z.title_en,'title_es',z.title_es,'mode',z.mode,'assessment',z.assessment_config IS NOT NULL,'is_published',z.is_published,'mine',z.host_id=auth.uid(),'cover_path',z.cover_path,'on_team',z.on_team,'questions',CASE WHEN z.assessment_config IS NOT NULL THEN jsonb_array_length(coalesce(z.assessment_config->'questions','[]'::jsonb)) ELSE (SELECT count(*)::integer FROM quiz_questions WHERE quiz_id=z.id) END,'done',EXISTS(SELECT 1 FROM quiz_attempts WHERE quiz_id=z.id AND user_id=auth.uid() AND submitted_at IS NOT NULL),'updated_at',z.updated_at) ORDER BY z.updated_at DESC),'[]'::jsonb)
 FROM quizzes z WHERE z.offer_id IS NULL AND z.team_id=_team AND auth.uid() IS NOT NULL AND is_team_member(_team,ARRAY['leader','host','member']) AND (z.is_published OR z.host_id=auth.uid());
$function$;
